  "message": "I can check the exact reason for HAT039’s delay and the updated departure/arrival times, then discuss compensation options.",
  "required_information": {
    "flight_date": "Please provide the flight date for HAT039 (YYYY-MM-DD)."
  },
  "if_you_are_booked_on_this_flight": {
    "need_user_id": "Please provide your user ID so I can verify your profile and reservation.",
    "need_reservation_id": "If you have the reservation ID for this trip, please share it. If not, I can look it up once I have your user ID."
  },
  "compensation_policy_summary": {
    "eligibility": "Compensation can be considered if you are a silver or gold member, have travel insurance, or are flying in business class.",
    "for_delays": "If the delay is confirmed and you choose to change or cancel the reservation, I can offer a travel certificate as a gesture (typically $50 per passenger) after completing the change/cancel.",
    "note": "I need to confirm your eligibility and the delay status before issuing any certificate."
  },
  "options": [
    "Proceed to check the live status once you provide the flight date.",
    "If you wish to change or cancel due to the delay, let me know and I will outline the exact steps and any payment/refund method needed (using a payment method already on your profile)."
  ]
}

